---列表刷新
function OverseaStoreOptionalGiftNode:OnGetItemByIndex(listView, index)
    if index < 0 then return nil end
    local cell = listView:NewListViewItem("OverseaMallDIYGiftListNode")

    local cellData = self:GetProducts()[index + 1]
    local scr = CfUtils.GetLuaScr(cell, OverseaStoreConstants.ScrPath.OverseaStoreOptionalGiftCell)
    if scr then
        scr:RefreshCell(self:GetStoreType(), cellData)
    end
    return cell
end

